package duckdb_go_bindings

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func getTestDir(t *testing.T) string {
	path, err := os.Getwd()
	require.NoError(t, err)
	return filepath.Join(path, "test") + "/"
}

// TestOpenSQLiteDB ensures that extension auto install + load works,
// as well as some basic C API functions.
func TestOpenSQLiteDB(t *testing.T) {
	defer VerifyAllocationCounters()

	dsn := getTestDir(t) + "pets.sqlite"

	var config Config
	defer DestroyConfig(&config)
	if CreateConfig(&config) == StateError {
		t.Fail()
	}

	var db Database
	defer Close(&db)

	var errMsg string
	if OpenExt(dsn, &db, config, &errMsg) == StateError {
		require.Empty(t, errMsg)
	}

	var conn Connection
	defer Disconnect(&conn)
	if Connect(db, &conn) == StateError {
		t.Fail()
	}

	var res Result
	defer DestroyResult(&res)
	if Query(conn, `SELECT COUNT(*) FROM pets`, &res) == StateError {
		t.Fail()
	}

	colCount := int(ColumnCount(&res))
	require.Equal(t, 1, colCount)

	colType := ColumnType(&res, 0)
	require.Equal(t, TypeBigInt, colType)
}

//go:build duckdb_arrow

package duckdb_go_bindings

import (
	"testing"

	"github.com/apache/arrow-go/v18/arrow/array"
	"github.com/stretchr/testify/require"
)

func TestArrow(t *testing.T) {
	defer VerifyAllocationCounters()

	var config Config
	defer DestroyConfig(&config)
	if CreateConfig(&config) == StateError {
		t.Fail()
	}

	var db Database
	defer Close(&db)
	var errMsg string
	if OpenExt(":memory:", &db, config, &errMsg) == StateError {
		require.Empty(t, errMsg)
	}

	var conn Connection
	defer Disconnect(&conn)
	if Connect(db, &conn) == StateError {
		t.Fail()
	}

	var res Result
	defer DestroyResult(&res)
	if Query(conn, `FROM (
		VALUES (1, 'foo'), (2, 'bar'), (3, null)
	) AS t(a, b)
	`, &res) == StateError {
		t.Fail()
	}

	colCount := ColumnCount(&res)
	require.Equal(t, 2, int(colCount))

	names := make([]string, colCount)
	types := make([]LogicalType, colCount)
	for i := range colCount {
		names[i] = ColumnName(&res, i)
		types[i] = ColumnLogicalType(&res, i)
	}
	defer func() {
		for i := range colCount {
			DestroyLogicalType(&types[i])
		}
	}()
	// get arrow options
	opt := ArrowOptions{}
	ConnectionGetArrowOptions(conn, &opt)
	defer DestroyArrowOptions(&opt)

	// get schema
	schema, ed := NewArrowSchema(opt, types, names)
	defer DestroyErrorData(&ed)
	require.False(t, ErrorDataHasError(ed))
	require.Equal(t, 2, int(schema.NumFields()))

	// get data chunk
	chunk := FetchChunk(res)
	if chunk.Ptr == nil {
		t.Fatal("no data")
	}
	defer DestroyDataChunk(&chunk)

	rec, ed := DataChunkToArrowArray(opt, schema, chunk)
	defer DestroyErrorData(&ed)
	require.False(t, ErrorDataHasError(ed))
	defer rec.Release()

	require.Equal(t, 2, int(rec.NumCols()))
	require.Equal(t, 3, int(rec.NumRows()))
	if v, ok := rec.Column(0).(*array.Int32); ok {
		require.Equal(t, []int32{1, 2, 3}, v.Int32Values())
	} else {
		t.Fatalf("expected int32 column, got %T", rec.Column(0))
	}
	if v, ok := rec.Column(1).(*array.String); ok {
		require.Equal(t, "foo", v.Value(0))
		require.Equal(t, "bar", v.Value(1))
		require.True(t, v.IsNull(2))
	} else {
		t.Fatalf("expected String column, got %T", rec.Column(1))
	}

	newRec := array.NewRecordBatch(schema, rec.Columns(), rec.NumRows())
	defer newRec.Release()

	convSchema, ed := SchemaFromArrow(conn, newRec.Schema())
	defer DestroyErrorData(&ed)
	require.False(t, ErrorDataHasError(ed))
	defer DestroyArrowConvertedSchema(&convSchema)

	dataChunk, ed := DataChunkFromArrow(conn, newRec, convSchema)
	defer DestroyErrorData(&ed)
	require.False(t, ErrorDataHasError(ed))
	defer DestroyDataChunk(&dataChunk)

	cc := DataChunkGetColumnCount(dataChunk)
	require.Equal(t, colCount, cc)

	rc := DataChunkGetSize(dataChunk)
	require.Equal(t, IdxT(rec.NumRows()), rc)
}

//go:build duckdb_nightly

package duckdb_go_bindings

import (
	"fmt"
	"os"
	"runtime"
	"testing"

	"github.com/stretchr/testify/require"
)

const minDuckDBSourceIDLength = 7

func tempExtensionDirectory(t *testing.T) string {
	t.Helper()

	dir, err := os.MkdirTemp("", "duckdb-nightly-ext-*")
	require.NoError(t, err)
	t.Cleanup(func() {
		// DuckDB keeps loaded extension DLLs open for the process lifetime, so
		// Windows may not release the directory until go test exits.
		if err := os.RemoveAll(dir); err != nil && runtime.GOOS != "windows" {
			t.Error(err)
		}
	})
	return dir
}

func openNightlyConnection(t *testing.T) Connection {
	t.Helper()

	var config Config
	require.Equal(t, StateSuccess, CreateConfig(&config))
	require.Equal(t, StateSuccess, SetConfig(config, "extension_directory", tempExtensionDirectory(t)))

	var db Database
	var errMsg string
	require.Equal(t, StateSuccess, OpenExt(":memory:", &db, config, &errMsg), errMsg)

	var conn Connection
	require.Equal(t, StateSuccess, Connect(db, &conn))

	t.Cleanup(func() {
		Disconnect(&conn)
		Close(&db)
		DestroyConfig(&config)
	})
	return conn
}

func TestNightlyArtifactMatchesRequestedDuckDBCommit(t *testing.T) {
	expectedSHA := os.Getenv("DUCKDB_SHA")
	require.Regexp(t, `^[0-9a-f]{40}$`, expectedSHA, "DUCKDB_SHA must be a full lowercase hexadecimal commit SHA")

	conn := openNightlyConnection(t)

	// source_id is a commit prefix, so expectedSHA (validated hexadecimal above)
	// must start with it. error() reports the observed source_id on a mismatch.
	query := fmt.Sprintf(`
		SELECT CASE
			WHEN length(source_id) >= %[1]d AND starts_with('%[2]s', lower(source_id))
			THEN 1
			ELSE error(
				'linked DuckDB reports source_id ' || source_id ||
				', expected a hexadecimal prefix of at least %[1]d characters matching %[2]s'
			)
		END
		FROM pragma_version()
	`, minDuckDBSourceIDLength, expectedSHA)

	var result Result
	defer DestroyResult(&result)
	require.Equal(t, StateSuccess, Query(conn, query, &result), ResultError(&result))
	require.Equal(t, int64(1), ValueInt64(&result, 0, 0))
}

func TestNightlyArtifactInstallsAndLoadsHTTPFS(t *testing.T) {
	conn := openNightlyConnection(t)

	var result Result
	defer DestroyResult(&result)
	state := Query(conn, `
		FORCE INSTALL httpfs;
		LOAD httpfs;
		SELECT CAST(installed AND loaded AS BIGINT)
		FROM duckdb_extensions()
		WHERE extension_name = 'httpfs';
	`, &result)
	require.Equal(t, StateSuccess, state, ResultError(&result))
	require.Equal(t, int64(1), ValueInt64(&result, 0, 0))
}

